import {loadAssets,drawFeatures,path,hitProperty,roadDistance} from './tile-renderer.js';
const $=s=>document.querySelector(s),query=new URLSearchParams(location.search),preset=query.get('preset')||'ashtown-5000';
if(!/^[a-z0-9-]+$/.test(preset))throw Error('Invalid preset');
const base=`../${preset}/`,bake=query.has('bake'),canvas=$('#map'),ctx=canvas.getContext('2d',{alpha:false});
let runtime={apiBase:'',token:''};
addEventListener('message',e=>{if(e.origin!==location.origin||e.source!==parent||e.data?.type!=='atlas-runtime'||e.data.presetId!==preset)return;const url=e.data.apiBase||'';if(url&&!/^https?:\/\//.test(url))return;runtime={apiBase:url.replace(/\/$/,''),token:e.data.token||''}});
if(parent!==window)parent.postMessage({type:'atlas-runtime-ready',presetId:preset},location.origin);
if(bake)document.body.classList.add('bake');
const esc=s=>String(s??'—').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const json=async url=>{const api=url.startsWith('/atlas/api/');const r=await fetch(api?runtime.apiBase+url:url,api&&runtime.token?{headers:{Authorization:`Bearer ${runtime.token}`}}:{});if(!r.ok)throw Error(`${r.status}: ${url}`);return r.json()};
const manifest=await json(base+'tiles.json').catch(error=>{$('#name').textContent='Map unavailable';$('#status').textContent=error.message;throw error});
window.tileManifest=manifest;
await loadAssets();
$('#name').textContent=manifest.name;document.title=`${manifest.name} · Utilitysim`;
$('#coverage').textContent=`${manifest.premises.toLocaleString()} linked premises · ${manifest.roads.toLocaleString()} road segments. One shared coordinate system across ${manifest.tiles.length} vector tiles.`;
$('#system').href=`/?town=${preset}`;
const tileKeys=new Set(manifest.tiles),cache=new Map(),pending=new Map();
let view=[...manifest.bounds],features=[],selected=null,request=0,frameQueued=false,ready=false,overview=null,geometryOverview=null,selectionTicket=0,pickTicket=0;
const state={};for(const id of ['boundaries','roads','pools','names'])state[id]=false;state.stage='art';
const maxWidth=()=>{const {w,h}=dimensions();return Math.max(manifest.bounds[2],manifest.bounds[3]*w/h)*1.4};
function dimensions(){return {w:Math.max(1,canvas.clientWidth),h:Math.max(1,canvas.clientHeight),dpr:Math.min(devicePixelRatio||1,2)}}
function fit(){pickTicket++;const {w,h}=dimensions();const b=manifest.bounds,k=Math.max(b[2]/w,b[3]/h);view=[b[0]+b[2]/2-w*k/2,b[1]+b[3]/2-h*k/2,w*k,h*k]}
fit();
function pixelScale(){return canvas.clientWidth/view[2]}
function frame(b){pickTicket++;const {w,h,dpr}=dimensions(),width=Math.min(maxWidth(),Math.max(w*dpr/10,b[2])),height=width*h/w;view=[b[0]+b[2]/2-width/2,b[1]+b[3]/2-height/2,width,height];refresh()}
window.mapView={get:()=>[...view],frame};window.mapReady=false;
async function tile(key){if(cache.has(key))return cache.get(key);if(!tileKeys.has(key))return {features:[]};if(!pending.has(key))pending.set(key,json(base+`tiles/${key}.json`).then(t=>{cache.set(key,t);pending.delete(key);return t}).catch(e=>{pending.delete(key);throw e}));return pending.get(key)}
function visibleKeys(){const s=manifest.tileSize,keys=[];for(let x=Math.max(0,Math.floor(view[0]/s));x<=Math.floor((view[0]+view[2])/s);x++)for(let y=Math.max(0,Math.floor(view[1]/s));y<=Math.floor((view[1]+view[3])/s);y++){const k=`${x}-${y}`;if(tileKeys.has(k))keys.push(k)}return keys}
async function refresh(){const ticket=++request,ppu=pixelScale();schedule();const keys=visibleKeys();if(overview&&!bake&&ppu<.38){features=[];updateAccessible();ready=true;window.mapReady=true;schedule();return}try{const chunks=[];for(let i=0;i<keys.length;i+=12){chunks.push(...await Promise.all(keys.slice(i,i+12).map(tile)));if(ticket!==request)return}const unique=new Map();for(const t of chunks)for(const f of t.features)unique.set(f.type+':'+f.id,f);features=[...unique.values()].filter(f=>f.bbox[2]>=view[0]-12&&f.bbox[0]<=view[0]+view[2]+12&&f.bbox[3]>=view[1]-12&&f.bbox[1]<=view[1]+view[3]+12);updateAccessible();ready=true;window.mapReady=true;window.visibleFeatures=features;schedule(); // Bound tile cache without changing visible geometry.
if(cache.size>96&&!bake){const needed=new Set(keys);for(const k of cache.keys()){if(cache.size<=96)break;if(!needed.has(k))cache.delete(k)}}
}catch(e){$('#status').textContent=`Map tile unavailable: ${e.message}`}}
function schedule(){if(!frameQueued){frameQueued=true;requestAnimationFrame(()=>{frameQueued=false;draw()})}}
function draw(){const {w,h,dpr}=dimensions();if(canvas.width!==Math.round(w*dpr)||canvas.height!==Math.round(h*dpr)){canvas.width=Math.round(w*dpr);canvas.height=Math.round(h*dpr)}ctx.setTransform(1,0,0,1,0,0);ctx.fillStyle='#a3b17a';ctx.fillRect(0,0,canvas.width,canvas.height);const k=canvas.width/view[2];ctx.setTransform(k,0,0,k,-view[0]*k,-view[1]*k);if(overview)ctx.drawImage(state.stage==='geometry'&&geometryOverview?geometryOverview:overview,...manifest.bounds);if(features.length)drawFeatures(ctx,features,{...state,ppu:k,view});if(selected){ctx.save();if(selected.type==='property'){path(ctx,selected.rings);ctx.fillStyle='#ffe79e44';ctx.fill('evenodd');ctx.strokeStyle='#fff1b1';ctx.lineWidth=2/k;ctx.stroke()}else if(selected.type==='road'){ctx.beginPath();ctx.moveTo(...selected.points[0]);for(const p of selected.points.slice(1))ctx.lineTo(...p);ctx.lineWidth=selected.pavementWidthM;ctx.strokeStyle='#f3ca70b0';ctx.stroke()}ctx.restore()}const scaleM=10**Math.floor(Math.log10(100/pixelScale()));$('#scale').style.width=`${scaleM*pixelScale()}px`;$('#scale').textContent=scaleM>=1000?`${scaleM/1000} km`:`${scaleM} m`;$('#status').textContent=`${manifest.budget.homes.toLocaleString()} homes · ${manifest.budget.pools.toLocaleString()} pools · ${manifest.budget.solar} solar${ready?'':' · Loading…'}${pixelScale()<.38&&(state.boundaries||state.roads||state.pools||state.names)?' · Zoom in for inspection layers':''}`;window.renderStats={loadedTiles:cache.size,visibleFeatures:features.length,pixelsPerMetre:k,sourceRoofPixels:manifest.roofSourcePixels,bounds:[...view]}}
function zoom(f,c=[.5,.5]){const w=Math.min(maxWidth(),Math.max(canvas.clientWidth*dimensions().dpr/10,view[2]*f)),h=w*canvas.clientHeight/canvas.clientWidth;frame([view[0]+(view[2]-w)*c[0],view[1]+(view[3]-h)*c[1],w,h])}
function list(obj){return '<dl>'+Object.entries(obj).map(([k,v])=>`<dt>${esc(k)}</dt><dd>${esc(v)}</dd>`).join('')+'</dl>'}
async function select(f){pickTicket++;selected=f;const ticket=++selectionTicket;schedule();$('#inspector').show();$('#inspector .close').focus({preventScroll:true});if(f.type==='road'){$('#title').textContent=f.name;$('#details').innerHTML=list({'Segment':f.id,'Class':f.roadClass,'Length':`${f.lengthM} m`,'Pavement':`${f.pavementWidthM} m`,'Right of way':`${f.rowWidthM} m`,'Graph ends':`${f.a} → ${f.b}`})+'<p>This selection and the drawn road use the same saved centreline.</p>';return}const p=f.record;$('#title').textContent=p.address||p.id;$('#details').innerHTML=list({'Premise':p.id,'Use':p.buildingType,'Block':p.atlasBlockId,'Parcel':p.parcelId,'Building':p.buildingId,'Account':p.accountId,'Pool':p.hasPool?'Yes':'No','Solar':p.solar?'Yes':'No'})+`<p id="history">Checking simulation readings…</p><p><a href="/?town=${preset}&premise=${encodeURIComponent(p.id)}" id="openRecord">Open account & meter readings →</a></p>`;if(parent!==window)parent.postMessage({type:'atlas-premise',premiseId:p.id,presetId:preset},location.origin);try{const data=await json(`/atlas/api/premises/${encodeURIComponent(p.id)}/history?limit=1&town=${preset}`);if(ticket===selectionTicket)$('#history').textContent=`${data.totalDays} saved days · ${data.readings.length} saved meter observations on ${data.days[0]||'no saved date'}.`}catch{if(ticket===selectionTicket)$('#history').textContent='Connect the simulation runtime to inspect current readings.'}}
async function pick(x,y){const ticket=++pickTicket,s=manifest.tileSize,t=await tile(`${Math.floor(x/s)}-${Math.floor(y/s)}`);if(ticket!==pickTicket)return;const pp=t.features.filter(f=>f.type==='property');const f=pp.find(f=>hitProperty(f,x,y))||t.features.filter(f=>f.type==='road').find(f=>roadDistance(f,x,y)<=f.pavementWidthM/2);if(f)select(f)}
window.atlasMap={pick,select,refresh,manifest,cache,get features(){return features},async selectPremise(id){const request=++pickTicket,index=await json(base+'premise-index.json');if(request!==pickTicket)return;if(!index[id])throw Error('Unknown premise');const [x,y,c,r]=index[id];frame([x-90,y-60,180,120]);const ticket=pickTicket,t=await tile(`${c}-${r}`);if(ticket!==pickTicket)return;const f=t.features.find(f=>f.type==='property'&&f.id===id);if(f)await select(f)}};
$('#menu').onclick=()=>{$('#tools').hidden=!$('#tools').hidden;$('#menu').setAttribute('aria-expanded',String(!$('#tools').hidden))};
for(const id of ['boundaries','roads','pools','names'])$('#'+id).onchange=e=>{state[id]=e.target.checked;refresh()};$('#stage').onchange=e=>{state.stage=e.target.value;refresh()};
$('#whole').onclick=()=>{fit();refresh()};$('#centre').onclick=()=>{const f=manifest.focus||{x:manifest.bounds[2]/2,z:manifest.bounds[3]/2};frame([f.x-380,f.z-250,760,500])};
async function jump(kind){const ticket=++pickTicket,index=await json(base+'landmarks.json').catch(()=>null);if(ticket!==pickTicket)return;if(index?.[kind]){const [x,y]=index[kind];frame([x-160,y-110,320,220])}else{const center=manifest.focus||{x:view[0]+view[2]/2,z:view[1]+view[3]/2};frame([center.x-230,center.z-180,460,360])}}
$('#neighbourhood').onclick=()=>jump('residential');$('#industry').onclick=()=>jump('industrial');$('#plus').onclick=()=>zoom(.72);$('#minus').onclick=()=>zoom(1/.72);$('#inspector .close').onclick=()=>{$('#inspector').close();selected=null;selectionTicket++;pickTicket++;canvas.focus({preventScroll:true});schedule()};
function point(e){const r=canvas.getBoundingClientRect();return [view[0]+(e.clientX-r.left)/r.width*view[2],view[1]+(e.clientY-r.top)/r.height*view[3]]}
canvas.addEventListener('wheel',e=>{e.preventDefault();if(e.deltaY===0)return;zoom(e.deltaY>0?1.16:1/1.16,[e.offsetX/canvas.clientWidth,e.offsetY/canvas.clientHeight])},{passive:false});
let down=null,moved=false,pinch=0;const touches=new Map();canvas.addEventListener('pointerdown',e=>{touches.set(e.pointerId,[e.clientX,e.clientY]);down={x:e.clientX,y:e.clientY,b:[...view]};moved=false;canvas.setPointerCapture(e.pointerId);if(touches.size===2){const a=[...touches.values()];pinch=Math.hypot(a[0][0]-a[1][0],a[0][1]-a[1][1])}});
canvas.addEventListener('pointermove',e=>{if(!touches.has(e.pointerId))return;touches.set(e.pointerId,[e.clientX,e.clientY]);if(touches.size===2){const a=[...touches.values()],d=Math.hypot(a[0][0]-a[1][0],a[0][1]-a[1][1]);if(pinch>0&&d>0){const r=canvas.getBoundingClientRect();zoom(pinch/d,[((a[0][0]+a[1][0])/2-r.left)/r.width,((a[0][1]+a[1][1])/2-r.top)/r.height])}pinch=d;moved=true;return}if(!down)return;const dx=e.clientX-down.x,dy=e.clientY-down.y;if(Math.hypot(dx,dy)>4)moved=true;if(moved)frame([down.b[0]-dx*down.b[2]/canvas.clientWidth,down.b[1]-dy*down.b[3]/canvas.clientHeight,down.b[2],down.b[3]])});
canvas.addEventListener('pointerup',e=>{touches.delete(e.pointerId);if(touches.size===1){const [x,y]=[...touches.values()][0];down={x,y,b:[...view]};moved=true}else{if(down&&!moved)pick(...point(e));down=null}pinch=0});canvas.addEventListener('pointercancel',()=>{touches.clear();down=null;pinch=0});
canvas.addEventListener('keydown',e=>{if(e.key==='Enter'){e.preventDefault();pick(view[0]+view[2]/2,view[1]+view[3]/2)}if(['+','=','-','ArrowLeft','ArrowRight','ArrowUp','ArrowDown'].includes(e.key))e.preventDefault();if(e.key==='+'||e.key==='=')zoom(.8);if(e.key==='-')zoom(1.25);const pan={ArrowLeft:[-.1,0],ArrowRight:[.1,0],ArrowUp:[0,-.1],ArrowDown:[0,.1]}[e.key];if(pan)frame([view[0]+pan[0]*view[2],view[1]+pan[1]*view[3],view[2],view[3]])});document.addEventListener('keydown',e=>{if(e.key==='Escape'){$('#inspector').close();selected=null;selectionTicket++;pickTicket++;schedule()}});
addEventListener('resize',()=>frame([...view]));
if(!bake&&(await json(base+'overview.json').catch(()=>null))?.sourceSha256===manifest.sourceSha256){const im=new Image();im.src=base+'overview.webp';try{await im.decode();overview=im}catch{}const gm=new Image();gm.src=base+'geometry-overview.webp';try{await gm.decode();geometryOverview=gm}catch{}}
await refresh();if(query.get('premise'))await window.atlasMap.selectPremise(query.get('premise'));

function updateAccessible(){
 const list=$('#visibleRecords');if(!list)return;
 const items=features.filter(f=>f.type==='property'||f.type==='road').sort((a,b)=>a.id.localeCompare(b.id)).slice(0,200);
 list.innerHTML='<option value="">Select a visible property or road…</option>'+items.map(f=>`<option value="${esc(f.type+':'+f.id)}">${esc(f.type==='property'?f.record.address+' · '+f.id:f.name+' · '+f.id)}</option>`).join('');
}
$('#visibleRecords').onchange=e=>{const value=e.target.value;const f=features.find(f=>f.type+':'+f.id===value);if(f)select(f)};
